BANK=[]
def add(domain,topic,level,stem,options,explain,source,cli=None,kind=None,pairs=None):
    correct=[i for i,v in enumerate(options) if v.startswith('*')]
    BANK.append(dict(id=f'q{len(BANK)+1:03}',domain=domain,topic=topic,level=level,stem=stem,options=[v.lstrip('*') for v in options],correct=correct,explanation=explain,source=source,cli=cli,type=kind or ('multi' if len(correct)>1 else 'single'),pairs=pairs))
def rows(domain,text):
    for line in text.strip().splitlines():
        if not line.strip():continue
        p=line.split('|')
        assert len(p) in (7,8),(len(p),line)
        topic,level,source,stem,answer,wrong,why=p[:7]
        opts=['*'+a for a in answer.split('~')]+wrong.split('~')
        add(domain,topic,level,stem,opts,why,source,p[7].replace('\\n','\n') if len(p)==8 else None)
