match(0,'Ethernet & TCP/IP','Match each protocol to its primary role.',[['ARP','Resolve a local IPv4 neighbor MAC'],['DNS','Resolve names to records'],['DHCP','Supply host addressing parameters'],['NTP','Synchronize clocks']],'These services solve separate problems: link-layer resolution, naming, address configuration and time.','protocols')
