# 100 generated, deterministic applied exercises. Fixed stable IDs; never generated at runtime.
# Twenty subnet calculations exercise boundaries, broadcast, capacity and allocation.
for i in range(20):
    prefix=[25,26,27,28,29,30,23,22,21,20][i%10]
    net=ipaddress.ip_network(f'10.{40+i}.{17+i}.0/{prefix}',strict=False)
    host=ipaddress.ip_address(int(net.network_address)+min(13,net.num_addresses-2))
    task=i%4
    if task==0:
        ans=str(net.network_address); stem=f'An interface is {host}/{prefix}. What is its network address?'
        wrong=[str(host),str(net.broadcast_address),str(ipaddress.ip_address(int(net.network_address)+1))]
        why=f'A /{prefix} has {32-prefix} host bits. Clear those bits: the network is {net.network_address}; its broadcast is {net.broadcast_address}.'
    elif task==1:
        ans=str(net.broadcast_address);stem=f'For {host}/{prefix}, what is the subnet broadcast address?'
        wrong=[str(net.network_address),str(net.broadcast_address-1),str(net.network_address+1)]
        why=f'The block spans {net.network_address} through {net.broadcast_address}. Setting every host bit to 1 gives the broadcast; subtract one for the last usable host.'
    elif task==2:
        n=net.num_addresses;ans=str(n-2);stem=f'A conventional IPv4 LAN uses {net}. How many usable host addresses does it provide?'
        wrong=[str(n),str(n-1),str(n//2-2)];why=f'With {32-prefix} host bits there are 2^{32-prefix} = {n} addresses. Subtract the network and broadcast addresses to obtain {n-2}.'
    else:
        n=net.num_addresses-2; required=max(2,n-3); ans=f'/{prefix}';stem=f'VLSM planning requires {required} usable IPv4 hosts on one conventional LAN. What is the smallest block (longest prefix) that fits?'
        wrong=[f'/{prefix+1}',f'/{prefix-1}',f'/{prefix-2}'];why=f'/{prefix} supports {n} usable addresses. /{prefix+1} supports {net.num_addresses//2-2}, which is insufficient. Shorter prefixes fit but waste more space.'
    add(0,'IPv4 & subnetting','Interpretation',stem,['*'+ans]+wrong,why,'ipv4')
# Twenty routing lookups include more-specific, fallback and host-route outcomes.
for i in range(20):
    octet=60+i;base=f'10.{octet}'; target=[f'{base}.2.77',f'{base}.2.200',f'{base}.9.8',f'{base}.2.129'][i%4]
    cli=f'S* 0.0.0.0/0 [1/0] via 192.0.2.1\nS  {base}.0.0/16 [1/0] via 192.0.2.2\nO  {base}.2.0/24 [110/20] via 192.0.2.3\nO  {base}.2.128/25 [110/30] via 192.0.2.4\nS  {base}.2.129/32 [200/0] via 192.0.2.5'
    routes=[(ipaddress.ip_network('0.0.0.0/0'),1),(ipaddress.ip_network(base+'.0.0/16'),2),(ipaddress.ip_network(base+'.2.0/24'),3),(ipaddress.ip_network(base+'.2.128/25'),4),(ipaddress.ip_network(base+'.2.129/32'),5)]
    winner=max((x for x in routes if ipaddress.ip_address(target) in x[0]),key=lambda x:x[0].prefixlen)
    add(2,'Routing decisions','Interpretation',f'All shown routes are installed. Which next hop forwards a packet to {target}?',[('*' if n==winner[1] else '')+f'192.0.2.{n}' for n in range(1,6)],f'The most specific matching route is {winner[0]}, so use 192.0.2.{winner[1]}. Administrative distance has already influenced installation and does not override this lookup.','ad',cli)
# Fifteen ACL packet decisions: first-match logic, destination ports, and implicit deny.
for i in range(15):
    subnet=f'10.{100+i}.0';server=f'192.0.2.{20+i}'
    cli=f'ip access-list extended USERS\n 10 deny tcp host {subnet}.9 host {server} eq 443\n 20 permit tcp {subnet}.0 0.0.0.255 host {server} eq 443\n 30 permit udp {subnet}.0 0.0.0.255 any eq 53'
    src,proto,port=[(subnet+'.9','TCP',443),(subnet+'.10','TCP',443),(subnet+'.10','UDP',53),(subnet+'.10','TCP',80),('10.250.0.10','UDP',53)][i%5]
    correct=[0,1,2,3,3][i%5]
    actions=['Denied by entry 10','Permitted by entry 20','Permitted by entry 30','Denied by the implicit deny']
    why=[f'The exact source {src} and HTTPS destination match the first deny; the later subnet permit is never reached.',f'The source is in {subnet}.0/24, is not .9, and the TCP destination is {server}:443, so entry 20 is first.',f'The source is in the allowed subnet and the destination is UDP 53. Entry 30 permits it.',f'TCP destination port {port} matches neither HTTPS permission nor UDP DNS. No explicit permit applies.',f'The source is outside {subnet}.0/24. Even DNS is denied because no rule permits this source.'][i%5]
    add(4,'ACLs','Troubleshooting',f'The ACL is applied inbound. A packet from {src} to {server}, {proto} destination port {port}, arrives. What happens?',[('*' if j==correct else '')+a for j,a in enumerate(actions)],why,'acl',cli)
# Fifteen VLAN/STP/MAC diagnoses with concrete configuration evidence.
for i in range(15):
    v=100+i;kind=i%3
    if kind==0:
        cli=f'VLAN {v}: active on SW1 and SW2\nSW1 Gi0/1: trunking, allowed VLANs 10,20\nSW2 Gi0/1: trunking, allowed VLANs 10,20,{v}'
        stem=f'Peers in VLAN {v} work locally on both switches, but cannot communicate across their only interswitch link. Which change addresses the shown mismatch?'
        opts=[f'*Add VLAN {v} to the SW1 trunk allowed list','Change every client DNS server','Change the native VLAN on only SW2','Disable all VLANs except 1']
        why=f'SW1 does not allow VLAN {v} on the only path. Both ends must carry it; routing and DNS are not needed for same-VLAN Layer 2 traffic.';src='vlan';topic='VLANs & trunks'
    elif kind==1:
        p1=[4096,8192,16384,24576,28672][i//3];p2=32768
        cli=f'VLAN {v}\nSW-A bridge priority: {p1+v}, MAC: 00aa.0000.0001\nSW-B bridge priority: {p2+v}, MAC: 0001.0000.0001'
        stem='These are the only two bridges in the VLAN. Which becomes root?';opts=['*SW-A','SW-B','Both simultaneously','Cannot decide without IP addresses']
        why=f'SW-A has the lower bridge priority ({p1+v} versus {p2+v}). MAC is a tie-breaker only when the priority components are equal.';src='stp';topic='STP'
    else:
        cli=f'VLAN {v} forwarding ports: Gi0/1, Gi0/2, Gi0/3\nMAC table:\n{v} 00aa.0000.0001 DYNAMIC Gi0/1\n{v} 00bb.0000.0002 DYNAMIC Gi0/2'
        stem=f'A frame enters Gi0/3 in VLAN {v} with destination 00bb.0000.0002. Which port forwards it?';opts=['*Gi0/2 only','Gi0/1 and Gi0/2','Gi0/3 only','All ports in every VLAN']
        why=f'The destination MAC is known on Gi0/2 in VLAN {v}, so the switch unicasts the frame there. Flooding is unnecessary.';src='switch';topic='Ethernet & TCP/IP'
    add(1 if kind!=2 else 0,topic,'Interpretation',stem,opts,why,src,cli)
# Ten OSPF elections and cost computations, with explicit election conditions.
for i in range(10):
    if i<5:
        pri=[1,10,50,100,200][i];cli=f'Fresh election; all routers are present before election.\nRouter  Interface priority  Router ID\nR1      {pri}                  10.0.0.1\nR2      {pri}                  10.0.0.2\nR3      0                  10.255.255.255'
        stem=f'Broadcast segment {i+1}: which router is elected DR?';opts=['*R2','R1','R3','No DR is elected on broadcast networks'];why=f'R1 and R2 tie at priority {pri}, so router ID 10.0.0.2 wins. R3 is ineligible because its priority is zero.'
    else:
        ref=[1000,10000,100000,2000,20000][i-5];bw=[100,1000,10000,100,1000][i-5];cost=ref//bw
        cli=f'router ospf 1\n auto-cost reference-bandwidth {ref}\n! Outgoing interface bandwidth: {bw} Mbps\n! No manual ip ospf cost configured'
        stem=f'What OSPF cost is calculated for this interface (reference bandwidth in Mbps)?';opts=['*'+str(cost),str(cost+1),str(cost*10),'1'];why=f'Divide reference bandwidth by interface bandwidth: {ref}/{bw} = {cost}. The configured reference does not change physical speed.'
    add(2,'OSPF','Interpretation',stem,opts,why,'ospf',cli)
# Ten service interpretations: logging threshold and NAT address-role readings.
for i in range(10):
    if i<5:
        threshold=i+2;names=['emergencies','alerts','critical','errors','warnings','notifications','informational','debugging']; message=(i+4)%8
        stem=f'Logging trap level is {names[threshold]} ({threshold}). A level-{message} {names[message]} message occurs. Is it sent to the remote syslog server?'
        yes=message<=threshold;opts=[('*' if yes else '')+'Yes, it meets the severity threshold',('*' if not yes else '')+'No, it is less severe than the threshold','Only if the hostname matches','Only if it uses TCP port 22'];why=f'The configured threshold includes levels 0 through {threshold}. Level {message} is '+('included.' if yes else 'outside that range.');src='log';topic='NTP & monitoring';cli=f'logging host 192.0.2.50\nlogging trap {names[threshold]}'
    else:
        local=f'10.20.{i}.15';glob=f'203.0.113.{i+10}';ext=f'198.51.100.{i+20}'; role='inside local' if i%2 else 'inside global';ans=local if i%2 else glob
        stem=f'In this translation, which address is the {role}?';cli=f'Pro Inside global         Inside local          Outside local       Outside global\ntcp {glob}:41000 {local}:52000 {ext}:443 {ext}:443'
        opts=[('*' if x==ans else '')+x for x in [local,glob,ext,'192.0.2.1']];why=f'The {role} address is {ans}. Inside local describes the internal host before translation; inside global is its translated representation.';src='nat';topic='NAT & PAT'
    add(3,topic,'Interpretation',stem,opts,why,src,cli)
